await page.goto('https://www.apache.org/licenses/LICENSE-2.0.html');
await page.evaluate(() => {
  const heading = document.querySelector('h1')?.innerText || document.title;
  return cu.claim({key_text: heading, answer: heading});
});

await page.goto('https://curl.se/docs/manpage.html');
return await page.evaluate(() => {
  const h1 = document.querySelector('h1')?.innerText?.trim();
  return cu.claim({key_text: 'curl command line tool', answer: h1});
});

await page.goto('https://curl.se/docs/manpage.html');
return await page.evaluate(() => {
  const h1 = document.querySelector('h1')?.innerText?.trim();
  return cu.claim({key_text: h1, answer: h1});
});

await page.goto('https://www.iban.com/currency-codes');
await page.getByText('Japan', {exact:true}).first();
return await page.evaluate(() => cu.claim({key_text: 'Japan', answer: cu.text('Japan')}));

await page.goto('https://www.sqlite.org/rescode.html');
return await page.evaluate(() => {
  const text = document.body.innerText;
  const match = text.match(/\b5\s+SQLITE_BUSY\b/);
  return cu.claim({key_text: match ? match[0] : 'SQLITE_BUSY', answer: 'SQLITE_BUSY'});
});

await page.goto('https://www.nist.gov/pml/owm/metric-si');
await page.getByText(/deka/i).first().isVisible();
await page.evaluate(() => cu.claim({key_text: 'deka', answer: cu.text('deka')}));

await page.goto('https://www.nist.gov/pml/owm/metric-si-prefixes');
await page.getByText(/deka/i).first().isVisible();
await page.evaluate(() => {
  const row = [...document.querySelectorAll('tr')].find(r => /\bdeka\b/i.test(r.innerText));
  const text = row ? row.innerText : document.body.innerText.match(/.{0,80}\bdeka\b.{0,120}/i)?.[0];
  const symbol = row ? [...row.querySelectorAll('td,th')].map(c => c.innerText.trim()) : [];
  return cu.claim({key_text: text || 'deka', answer: symbol.length ? symbol[symbol.findIndex(v => /^deka$/i.test(v)) + 1] : text});
});

await page.goto('https://practice.expandtesting.com/form-validation');
await cu.fill('Contact name', 'Alex Example');
await cu.fill('Contact number', '012-3456789');
await cu.fill('Pickup date', '15 January 2030');
await cu.click('Card');
await cu.click('Submit');
await page.evaluate(() => cu.claim({key_text: 'Thank you', answer: document.body.innerText.match(/Thank you[^\n.]*(?:\.)?/i)?.[0] || cu.text('Thank you')}));

await page.goto('https://practice.expandtesting.com/form-validation');
await cu.fill('Contact Name', 'Alex Example');
await cu.fill('Contact number PickUp Date', '012-3456789');
await page.locator('input[type="date"]').fill('2030-01-15');
await page.getByRole('combobox', {name: 'Payment Method'}).selectOption({label: 'card'});
await cu.click('Register');
await page.evaluate(() => cu.claim({key_text: document.body.innerText.includes('Thank you') ? 'Thank you' : document.body.innerText.split('\n').filter(Boolean).slice(-4).join(' '), answer: (document.body.innerText.match(/Thank you[^\n]*/i) || [document.body.innerText.split('\n').filter(Boolean).slice(-1)[0]])[0]}));
